/*
 * Auxiliary logic-model test for the CVE-2023-38432 port guard.
 *
 * This does NOT build the kernel. It reproduces the exact arithmetic of the
 * guard added by the candidate patch to fs/ksmbd/smb2misc.c and checks the
 * security boundary:
 *
 *   req_struct_size = le16_to_cpu(pdu->StructureSize2) + __SMB2_HEADER_STRUCTURE_SIZE;
 *   if (command == SMB2_LOCK_HE)
 *           req_struct_size -= sizeof(struct smb2_lock_element);
 *   if (req_struct_size > len + 1)
 *           return 1;   // reject
 *
 * Constants taken from the target tree:
 *   __SMB2_HEADER_STRUCTURE_SIZE  = 64          (fs/ksmbd/smb2pdu.h:129)
 *   sizeof(struct smb2_lock_element) = 24       (8+8+4+4, __packed)
 *   SMB2_ERROR_STRUCTURE_SIZE2    = 9           (fs/ksmbd/smb2pdu.h:201)
 *   OP_BREAK_STRUCT_SIZE_20/21    = 24 / 36     (fs/ksmbd/smb2pdu.h:1409/1410)
 */
#include <stdio.h>
#include <stdint.h>

#define SMB2_HEADER_STRUCTURE_SIZE 64u
#define SMB2_LOCK_ELEMENT_SIZE     24u
#define SMB2_LOCK_HE               0x000Au
#define SMB2_OPLOCK_BREAK_HE       0x0012u

/* candidate guard: returns 1 when the declared payload does not fit in len */
static int new_guard(uint16_t structure_size2, uint32_t len, int is_lock)
{
	uint32_t req_struct_size = (uint32_t)structure_size2 + SMB2_HEADER_STRUCTURE_SIZE;

	if (is_lock)
		req_struct_size -= SMB2_LOCK_ELEMENT_SIZE;

	return req_struct_size > len + 1;
}

static int failures = 0;

static void expect(const char *name, int got, int want)
{
	printf("%-72s got=%d want=%d %s\n", name, got, want, got == want ? "PASS" : "FAIL");
	if (got != want)
		failures++;
}

int main(void)
{
	/* Positive path: a correctly sized frame is accepted. */
	expect("normal cmd, size2=8, len=72 (64+8) -> accept",
	       new_guard(8, 72, 0), 0);
	expect("normal cmd, size2=8, len=73 (one implied bcc byte) -> accept",
	       new_guard(8, 73, 0), 0);
	/* Boundary exactly at req == len+1 -> accept. */
	expect("boundary req_struct_size == len+1 -> accept",
	       new_guard(8, 71, 0), 0);   /* 8+64=72 == 71+1 */
	expect("boundary req_struct_size == len+2 -> reject",
	       new_guard(8, 70, 0), 1);   /* 72 > 71 */

	/* Negative path: CVE trigger - declared size far exceeds received frame. */
	expect("CVE: size2=0xffff, len=100 -> reject",
	       new_guard(0xffff, 100, 0), 1);
	expect("CVE: size2=4096, len=96 -> reject",
	       new_guard(4096, 96, 0), 1);

	/* Cases the OLD check let through without any length bound. */
	expect("error packet size2=9, len=64 (short) -> reject",
	       new_guard(9, 64, 0), 1);    /* 73 > 65 */
	expect("error packet size2=9, len=72 (fits) -> accept",
	       new_guard(9, 72, 0), 0);    /* 73 <= 73 */
	expect("oplock break size2=20, len=64 (short) -> reject",
	       new_guard(20, 64, 0), 1);   /* 84 > 65 */
	expect("oplock break size2=21, len=64 (short) -> reject",
	       new_guard(21, 64, 0), 1);   /* 85 > 65 */
	expect("oplock break size2=20, len=83 (fits) -> accept",
	       new_guard(20, 83, 0), 0);   /* 84 <= 84 */

	/* SMB2_LOCK: one smb2_lock_element is subtracted from the required size. */
	expect("SMB2_LOCK size2=48 len=83 -> accept (48+64-24=88 <= 84? no)",
	       new_guard(48, 83, 1), 1);   /* 88 > 84 */
	expect("SMB2_LOCK size2=48 len=87 -> accept (req 88 == len+1)",
	       new_guard(48, 87, 1), 0);
	expect("SMB2_LOCK inflated size2=1000 len=200 -> reject",
	       new_guard(1000, 200, 1), 0);

	printf("\n%s (%d failure(s))\n", failures ? "MODEL TEST FAILED" : "MODEL TEST PASSED", failures);
	return failures ? 1 : 0;
}

